def transform(df):
    medians_by_pclass_age = df.groupby('Pclass')['Age'].median()

    def fill_age(row):
        pclass = row['Pclass']
        if pd.isnull(row['Age']):
            return medians_by_pclass_age[pclass]
        return row['Age']
    df['Age'] = df.apply(fill_age, axis=1)
    df['Age'] = df.groupby('Pclass')['Age'].apply(lambda x: x.fillna(x.median()))
    return df
